template <bool sync = true>
__aicore__ inline void IterateAll(
    const GlobalTensor<DstT>& gm, uint8_t enAtomic = 0, bool enSequentialWrite = false, bool waitIterateAll = false,
    bool fakeMsg = false)
{
    ASCENDC_ASSERT((!ToMatmulConfig(MM_CFG).isPartialOutput), {
        KERNEL_LOG(KERNEL_ERROR, "IterateAll is not supported for PartialOutput.");
    });
    if constexpr (BASE_MODULE::POLICY::POLICY_TYPE == PolicyType::MATMUL_NBUFFER_33) {
        static_assert(DoMatmulMDL(MM_CFG), "NBuffer33MatmulPolicy only support MDL config.");
        MATMUL_MODULE(Scheduler)->Schedule(gm, enAtomic, enSequentialWrite);
    } else {
        if constexpr (ToMatmulConfig(MM_CFG).intraBlockPartSum) {
            MATMUL_MODULE(MatmulSubBlockInfo)->SetFakeMsg(fakeMsg);
            MATMUL_MODULE(Scheduler)->Schedule(gm, enAtomic, enSequentialWrite, fakeMsg);
        } else {
            while (BASE_MODULE::Iterate()) {
                BASE_MODULE::GetTensorC(gm, enAtomic);
            }
        }
    }
}

__aicore__ inline bool MoveNext()
{
    bool ret = false;
    if constexpr (ToMatmulConfig(MM_CFG).singleCoreM != 0 && GetMIter(MM_CFG) == 1 && GetNIter(MM_CFG) == 1) {
        // only iterate once
        if (unlikely(isFirstIter_)) {
            ret = MoveOnFirstIterate();
        } else {
            ret = false;
        }
    } else {
        ret = MoveNextMulti();
    }
    return ret;
}

__aicore__ inline bool MoveOnFirstIterate()
{
    // start MLoop and NLoop on the first iteration
    MATMUL_MODULE(MLoop)->OuterStart();
    MATMUL_MODULE(MLoop)->InnerStart();
    MATMUL_MODULE(NLoop)->OuterStart();
    MATMUL_MODULE(NLoop)->InnerStart();
    isFirstIter_ = false;
    return true;
}

__aicore__ inline bool MoveNextMulti()
{
    if (unlikely(isFirstIter_)) {
        return MoveOnFirstIterate();
    } else {
        if constexpr (ToMatmulConfig(MM_CFG).iterateOrder == IterateOrder::ORDER_N) {
            return MoveOnIterateOrderN();
        } else if constexpr (ToMatmulConfig(MM_CFG).iterateOrder == IterateOrder::ORDER_M) {
            return MoveOnIterateOrderM();
        } else {
            if (likely(
                    MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetIterateOrder() ==
                    static_cast<int>(IterateOrder::ORDER_M))) {
                return MoveOnIterateOrderM();
            } else {
                ASCENDC_ASSERT(
                    (MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetIterateOrder() ==
                     static_cast<int>(IterateOrder::ORDER_N)),
                    {
                        KERNEL_LOG(
                            KERNEL_ERROR, "iterateOrder is %d , which should be ORDER_N",
                            MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetIterateOrder());
                    });
                return MoveOnIterateOrderN();
            }
        }
    }
    return true;
}

__aicore__ inline bool MoveOnIterateOrderN()
{
    if constexpr (DoMatmulIBShareNorm(MM_CFG) && A_TYPE::ibShare) {
        ASCENDC_ASSERT(
            (MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetStepM() >= MATMUL_MODULE(MLoop)->GetTotalIter()), {
                KERNEL_LOG(
                    KERNEL_ERROR, "When iterateOrder is orderN and A is IBShare, stepM >= mIter is required");
            });
    }
    // when M inner loop is finished, clear right matrix's data in L1 buffer, and restart M inner loop
    if (!MATMUL_MODULE(MLoop)->InnerNext()) {
        MATMUL_MODULE(CopyCubeInB)->Reset();
        MATMUL_MODULE(MLoop)->InnerStart();
        // when N outer and inner loop both are finished, clear left matrix's data in L1 buffer,
        // and restart N outer and inner loop.
        if (!MATMUL_MODULE(NLoop)->InnerNext()) {
            if (!MATMUL_MODULE(NLoop)->OuterNext()) {
                MATMUL_MODULE(NLoop)->OuterStart();
                MATMUL_MODULE(NLoop)->InnerStart();
                MATMUL_MODULE(CopyCubeInA)->Reset();
                // when M outer loop is finished, all the iterations are finished, end process
                if (!MATMUL_MODULE(MLoop)->OuterNext()) {
                    return false;
                }
                // N loop is restarted, M inner loop should be restarted
                MATMUL_MODULE(MLoop)->InnerStart();
            }
        }
    }
    return true;
}

__aicore__ inline bool MoveOnIterateOrderM()
{
    if constexpr (DoMatmulIBShareNorm(MM_CFG) && B_TYPE::ibShare) {
        ASCENDC_ASSERT(
            (MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetStepN() >= MATMUL_MODULE(NLoop)->GetTotalIter()), {
                KERNEL_LOG(
                    KERNEL_ERROR, "When iterateOrder is orderM and B is IBShare, stepN >= nIter is required");
            });
    }
    // when N inner loop is finished, clear left matrix's data in L1 buffer, and restart N inner loop
    if (!MATMUL_MODULE(NLoop)->InnerNext()) {
        MATMUL_MODULE(CopyCubeInA)->Reset();
        MATMUL_MODULE(NLoop)->InnerStart();
        // when M outer and inner loop both are finished, clear right matrix's data in L1 buffer,
        // and restart M outer and inner loop
        if (!MATMUL_MODULE(MLoop)->InnerNext()) {
            if (!MATMUL_MODULE(MLoop)->OuterNext()) {
                MATMUL_MODULE(MLoop)->OuterStart();
                MATMUL_MODULE(MLoop)->InnerStart();
                MATMUL_MODULE(CopyCubeInB)->Reset();
                // when N outer loop is finished, all the iterations are finished, end process
                if (!MATMUL_MODULE(NLoop)->OuterNext()) {
                    return false;
                }
                // M loop is restarted, N inner loop should be restarted
                MATMUL_MODULE(NLoop)->InnerStart();
            }
        }
    }

    __aicore__ inline void SetSingleShape(int32_t singleShape)
    {
        if constexpr (ToMatmulConfig(MM_CFG).singleCoreN != 0 && !ToMatmulConfig(MM_CFG).enableSetTail) {
            SetSingleShapeFromCFG();
        } else {
            SetSingleShapeFromTiling(singleShape);
        }
        ASCENDC_ASSERT((totalIter_ > 0), {
            KERNEL_LOG(
                KERNEL_ERROR, "invalid singleCoreN, totalIter_ is %d , which should be larger than 0", totalIter_);
        });
    }

    __aicore__ inline uint32_t GetTotalIter() const { return totalIter_; }

    __aicore__ inline bool OuterNext()
    {
        if constexpr (IsBasicN(MM_CFG)) {
            return false;
        } else {
            innerStartIdx_ += innerIter_;
            UpdateOuterParams();
            return !OuterEnd();
        }
    }

    __aicore__ inline void OuterStart()
    {
        innerStartIdx_ = 0;
        UpdateOuterParams();
    }

    __aicore__ inline bool OuterEnd()
    {
        if constexpr (IsBasicN(MM_CFG)) {
            return true;
        } else {
            return innerStartIdx_ >= totalIter_;
        }
    }

    __aicore__ inline uint32_t GetOuterIdx() const
    {
        return Ceil(innerStartIdx_, MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetStepN());
    }

    __aicore__ inline uint32_t GetOuterIter() const
    {
        return Ceil(totalIter_, MATMUL_MODULE(MatmulShapeTiling)->GetTiling().GetStepN());
    }

    __aicore__ inline int32_t GetTileShape() const { return baseShape_; }

    __aicore__ inline int32_t GetTileBlockShape() const { return baseBlockShape_; }

    __aicore__ inline int32_t GetTailShape() const { return tailBaseShape_; }

    __aicore__ inline bool InnerNext()
    {
        if constexpr (IsBasicN(MM_CFG)) {
            return false;
        } else {
            ++innerIndex_;
            UpdateInnerParams();
            return !InnerEnd();
        }
    }

    __aicore__ inline void InnerStart()
    {
        innerIndex_ = innerStartIdx_;
        UpdateInnerParams();
    }

    __aicore__ inline bool InnerEnd() { return innerIndex_ >= innerStartIdx_ + innerIter_; }

    __aicore__ inline uint32_t GetInnerIdx() const { return innerIndex_; }

    __aicore__ inline uint32_t GetInnerIter() const { return innerIter_; }

    __aicore__ inline int32_t GetBaseShape() const { return baseShape_; }

    __aicore__ inline int32_t GetBaseBlockShape() const { return baseBlockShape_; }

